    faq_a_nm_me_card: "Yes. In \"My character\" (tap Sky in New Me), every stage of Sky you've already reached has a small share button in its corner. It makes a glass card as a picture – Sky glowing on a night sky, the stage, your first name, your day in the journey and your keys – and opens the share window, so you can send it on WhatsApp or save the picture. It's only a picture, so friends can see it but not take your Sky.",
