    bag_examples_v2_toast: "🎁 New examples in your bag: gift ideas, a hotel list and a flight list ✨",
    faq_a_bag_examples_list: "A new bag comes with examples you can change or delete like anything else: Home (shopping, recipes, the week's meals), Family (little moments, a birthday checklist, activities), Ideas (weekend ideas, gift ideas by how close the person is, and what to do with money you saved) and Trips (places you want to go, what to pack for a day trip, a hotel list and a checklist for flying abroad). A bag that already existed gets the newest ones once, into its own pockets.",
    faq_q_bag_examples_list: "What examples come in My Bag?",
    faq_a_shop_basics: "When the Shopping List is completely empty – for example at the very beginning – a basic list to start with appears: milk, bread, eggs and more. A tap on an item adds it to the list, and \"Add them all\" adds everything at once. As soon as something is on the list, the basic list disappears.",
    faq_q_shop_basics: "What is the basic list in an empty Shopping List?",
    faq_a_nm_me1_guide: "Sky – your character in New Me, in his first form (Sky 1). The first time, right after joining, a portal of light opens with sparkles all around and Sky flies out of it, explains in a few taps what's ahead, and then stays next to every question: while the meals are chosen he writes with you in his book, and a tap on his tip shows another one. At the end Sky celebrates with you and takes you on a short tour – and when the tour ends, he has one more little moment with you. If you leave in the middle – of the questions or the tour – next time Sky is happy to see you and asks whether to continue from the same place.",
    faq_q_nm_me1_guide: "Who guides the way into New Me?",
    nm_m1_day_text: "Every day – a ✓ on each meal, and I'll count everything for you.",
    nm_m1_go: "Let's go",
    nm_m1_heart_btn: "Together",
    nm_m1_heart_text: "Step by step. I'm here – always.",
    nm_m1_heart_title: "Let's walk this path together",
    nm_m1_hi_text: "From today I'm right here with you – every step of the way.",
