    nm_m1_joy_btn: "A quick tour",
    nm_m1_joy_text: "Your menu is waiting, and the magical world is already waking up.",
    nm_m1_joy_title: "Yay! It's all ready",
    nm_m1_magic_text: "And every real step forward you take opens more places in the magical world",
    nm_m1_menu_text: "Together we'll build a menu that fits you exactly: food you love, at times that suit you.",
    nm_m1_portal: "A new world is opening",
    nm_m1_q_about: "Nice to meet you!",
    nm_m1_q_agree: "Before we begin – a few important words",
    nm_m1_q_letter: "Words for your future self? I'll keep them safe for you",
    nm_m1_q_menu: "Let's write down the dreams together – and make them come true together",
    nm_m1_q_plan: "You can switch anytime – there's no wrong choice here.",
    nm_m1_q_times: "Your times are my times too",
    nm_m1_ready_text: "First a few small questions – then we'll choose the meals together.",
    nm_m1_skip: "Skip",
    nm_m1_tip_ai: "A food that isn't on the list? Later, in \"Swap\", you can write it in your own words – and AI will work it out. And now, let's choose together what to eat each day.",
    nm_m1_tip_love: "And if you don't love something – you can always swap it with AI. No matter which food – if you love it, it stays on the menu.",
    nm_m1_tip_rice: "I love rice the most – it'll be my base, so I'll pick it. I recommend going with what's familiar and tasty.",
