    room_genie_again_yes: "Yes",
    room_genie_bye: "See you",
    room_genie_rest: "The forest spirit is resting now – come back tomorrow ✨",
    faq_a_shop_holidays: "In the Shopping List, tap the gift: the holidays of your country (from Settings) appear in order, with their dates – calculated automatically every year. Tap a holiday for a ready list of what people buy for it; everything is selected (whatever is already on your list is not), untick what you don't need and tap \"Add to the list\". Two weeks before a holiday a small card appears at the top of the list; ✕ hides it until the next holiday.",
    faq_q_shop_holidays: "How does \"What to buy for the holiday\" work?",
    shop_hol_add: "Add to the list ({n})",
    shop_hol_added: "Added to the list: {n}",
    shop_hol_btn: "What to buy for the holiday",
    shop_hol_items_title: "{holiday} – what to buy?",
    shop_hol_not_now: "Not now",
    faq_a_shop_delivery: "In the Shopping List, tap the truck: choose what's in the delivery (everything is selected), when it arrives – today, tomorrow or another day – and at what time (morning, midday, evening, or \"Other…\" for your own hours). Those items move to an \"On the way\" card at the top of the list, with the day and the hours. When the day comes, \"Did the delivery arrive?\" appears in My Day (and the card has \"Did it arrive?\"). If everything arrived – they go to \"Buy again\". If something's missing, tap what didn't arrive and it goes straight back to the list.",
    faq_a_shop_departments: "The list sorts itself by supermarket departments – fruit & vegetables, bread, dairy & eggs, meat & fish, pantry, frozen, drinks, snacks, cleaning, personal care, baby and pets – so you walk the aisles in order. It's recognized from the item's name. If an item landed in the wrong place, tap it and pick its department, or \"Other…\" to write your own.",
    faq_a_shop_share_qty: "Yes. Next to each item, + adds one more (×2, ×3…) and − takes one off. The share button at the top of the Shopping List sends the whole list, neatly sorted by department, on WhatsApp, by email or as a copy.",
    faq_a_shop_two_buttons: "Both mean \"bought\". ✕ is for something you buy once – it leaves the list (and waits in the archive 🗑️ in case it was a mistake). ↺ is for things you buy again and again – it leaves the list and waits in \"Buy again\": the small ↺ button next to the bin at the bottom of the list opens it, and one tap there puts an item back on the list. Under \"Edit\" in it you can take an item out. When you add an item, things you bought before show up as suggestions, and if it's already on the list it just becomes ×2 instead of a second line.",
    faq_q_shop_delivery: "How does \"I ordered a delivery\" work?",
