    nm_swap_time: "Time",
    faq_a_new_me_challenge_journal: "When a challenge ends – big, mini or the challenge of the week – the celebration has a 📝 How did it go? button. It opens a page in the challenge journal: how it felt (five faces), what helped, what was hard and what I take with me – none of it is required, and it can also wait for later. The journal is a diamond in the magic bag: every finished challenge with its date and what was written, the newest first – tap one to read, edit or share it (only what is on the page is shared). A finished challenge also gets a medal in the achievements, under “Challenges I finished”. The challenge journal is separate from the diary.",
