    nm_chj_title: "Challenge journal",
    nm_chj_write: "Write how it went",
    faq_a_ai_reminder_in_text: "Yes – write it together with the task, for example “tomorrow at 17:00 pick up the package, with a reminder an hour before”. The reminder is saved on the task itself: an hour before, half an hour, the day before and so on, and “remind me” without a time means 10 minutes before. A reminder written in the text comes before the reminder field in the same window.",
    faq_q_ai_reminder_in_text: "Can I ask the AI assistant for a reminder in the same request?",
    myday_meals_all_done: "All of today's meals are checked 🍽️",
    nm_tour_week_text: "A small challenge for the week. ✓ every day – a key at the end.",
    books_home_chip: "{title} · p. {page}",
    books_home_of: "of {total}",
    books_home_off_toast: "The book left the home screen",
    books_home_on_toast: "The book is on the home screen 📖",
    books_home_pin: "On the home screen",
    books_home_q: "Which page am I on?",
    books_home_save: "Save",
    faq_a_books_home_chip: "Yes. In the Reading Corner, on the card of a book you are reading, tap 📌 On the home screen. A small button with the book and the page appears under the greeting on the home screen – tap it, type the new page number and save, and the progress is tracked (in the Reading Corner too). Tapping 📌 again takes it off. Several books can be there together – a button for each – and it is the same on every device.",
    faq_a_room_genie: "On the porch by the sea, a tap on Aladdin's lamp brings out the forest spirit – and a conversation starts: what is your wish (what would you like to change in your life), how it will feel when it comes true, what is hard on the way, and how the situation right now can be turned into something good. Then roughly how long it will take, a first small step and two more, and an “if… then…” for when it gets hard. At the end the whole wish appears step by step, and it can become a goal in My Goals (the steps become stations on the path, with a date by the time chosen; everything can be changed there) or be saved in the diary – and then the spirit says goodbye. Nothing is saved unless one of them is chosen. From the second visit on, the spirit first asks whether you'd like to change something else in your life: yes – the same conversation; not right now – a reminder to reach the goals already set. The spirit comes out once a day: after a wish is saved (or after “Not right now”), it rests until tomorrow. The questions follow a well-known way of turning a wish into a plan: wish, outcome, obstacle and plan.",
    faq_q_books_home_chip: "Can I see my book and page on the home screen?",
    faq_q_room_genie: "What does the genie of the lamp do?",
    room_genie_diary_done: "Saved in the diary",
    room_genie_feel_q: "And if it comes true – what is the best thing that will happen? How will it feel?",
    room_genie_goal_done: "Saved in My Goals – the steps are stations on the path",
    room_genie_hard_q: "What is the hardest part on the way? What holds you back from inside?",
