    room_genie_to_goal: "✨ Turn it into a goal in My Goals",
    room_genie_turn_ex: "For example: living at home is hard – but outside will be hard too. So what does home give right now that can be used?",
    room_genie_turn_q: "Sometimes what is hard is also the chance. How can the situation right now be turned into something good?",
    faq_a_new_me_week_challenge: "A small challenge for one week, chosen by you. In the hallway there's a big card: “What would you like to work on this week?” – tap it, pick an area (with myself, with others, learn and grow, calm, small brave steps, home and routine) and a challenge, and choose when it starts. The same challenges are also in the challenges screen, under 🌱 Personal growth. Every day ✓ on the card (one free day a week), and every week that ends brings a new key for the secret world. “Read 2 pages a day” ticks itself from the pages logged in the Reading Corner. When a week ends, 📌 Keep it as a daily task adds it to My Routine at the time you choose, with a ✓ every day. One challenge of the week runs at a time; the big and mini challenges keep going alongside it.",
    faq_q_new_me_week_challenge: "What is the challenge of the week?",
