    nm_me_choose: "Choose",
    nm_me_on_screen: "On screen",
    faq_a_new_me_game: "In New Me the game buttons always stay in the same place – in the hallway, in the secret room and everywhere in the forest; only the painting in the middle changes. At the top: the day in the journey, keys, streak and today's energy (how much was eaten out of the plan), and under it the next mission – the next meal at its time (a tap opens it, with ✓ I ate it). On the side: the whole day, challenges and my journey, and next to them the challenge of the week – its 7 days and a ✓ for today. At the bottom: the magic bag (everything in New Me – the world map, my journey, shopping, achievements, the challenge journal, measurements, photos, the monthly calendar, the daily table, reminders, the menu PDF and settings; it opens as its own screen). The world map, the first thing in the bag, shows every place in the forest – tap a place to go there; a locked place shows how many keys it needs. Sky is your character on the forest path: he starts as Sky 1, after a few challenges (4 keys) he grows into Sky 2 and near the end (9 keys) into Sky 3 – with a makeover you can watch. Tap Sky to see every stage – any stage already reached can be chosen again, so an earlier one can come back. Sky floats – drag him with a finger or the mouse, and the entrance he touches opens (a locked one shows how many keys are missing). Sky also comes along into every room and place and floats wherever you leave him: drag him anywhere, and drag the glowing ring under him to turn him all the way around; he faces the way he moves (on a computer: the arrows move him, Q and E turn him). In the hallway, the small 🏠 under the top bar goes back to the home screen; in every room and place, the button in the same corner goes back to the hallway.",
    faq_q_new_me_game: "How do the game buttons, the world map and Sky work?",
