    faq_a_new_me_menu_build: "First the questionnaire asks which meals you eat and when (2 meals + a snack, 2 meals + a light dinner, or both), and whether there's anything in the evening – to eat or to drink, what, and at what time. With \"2 meals + a snack\" the meals are lunch (11:30) and dinner (19:00), with the snack at 16:00. Then all the options for those meals appear. Pick up to 2 favourites for each meal – the menu shows \"this or that\". In some options (pita and spread, corn flakes and milk, something light) you pick up to 3 things you like, each in its own portion, and the menu shows \"this or that or that\"; the calories follow what you picked. Coffee and drinks work the same way. Every choice is balanced, so the day adds up to exactly 1,300 or 1,500. To change it at any time: ⚙️ Settings → 🍽️ Build your menu, or \"Pick up to 3 you like\" on the meal's card.",
    faq_q_new_me_menu_build: "How is the New Me menu built?",
