    faq_a_myday_water_toggle: "Yes. The water glass in 'My Day' (with + for one more glass) is on by default. To hide it, turn off \"Show water in 'My Day'\" in Settings > Personalization & Calendar. Nothing is deleted – Water Tracking keeps working, and turning the switch back on brings the glass back.",
    faq_q_myday_water_toggle: "Can I hide the water in 'My Day'?",
    myday_water_toggle_label: "Show water in 'My Day'",
    faq_a_routine_newme_sync: "With New Me, My Routine's ⚙️ has a 'Sync with New Me' switch. On (the default), today's New Me meals appear in My Day and in My Routine – in place of the routine meals that were hidden. Off, the New Me meals leave both and the routine is back exactly as it was. Nothing is deleted – turning it on again brings everything back and asks which routine meals to hide.",
