    faq_a_food_list_languages: "The built-in food list started with Israeli foods and their Hebrew names. In every other language each food shows its English name, and the search finds any English name it knows (for example 'broth' finds Clear soup); foods that have only a Hebrew name aren't listed. Anything that isn't on the list can simply be written in your own words – the AI estimate works in every language.",
    faq_q_food_list_languages: "Why does the food list show English names, and fewer foods, in my language?",
    settings_copyright_line: "© 2026 all rights reserved. app developed by eden zabari.",
    workout_ready_replace_btn: "Replace",
    faq_a_sport_workout_ai: "In My workouts → ⋯ → Plan with AI (and when the table is empty, also on the tile next to the ready plans). Answer with a few taps – how many times a week, when, place, level and goal, most of them with \"Other\" too – and add a free line if you like, such as a sensitive knee or a 5K by summer. The AI builds a whole week: workout types, days, times, duration, intensity, exercises and rest days. Nothing is saved before a preview: \"Put it in my table\" (instead of the table or in addition to it), \"Another suggestion\" (up to 3 times) or \"Change answers\". The plan is moderate on purpose, and if you mention pain or an injury you get gentle options and a suggestion to check with a professional. It uses the same AI quota as the schedule and routine: 5 times free, and 60 a month with Premium.",
    faq_q_sport_workout_ai: "How do I build a workout plan with AI?",
    workout_ai_add: "Add to my table",
