    workout_ai_working: "Building your plan…",
    faq_a_sport_workout_jar: "Every type of workout has its own colored star – running pink, walking green, swimming blue and so on. Each workout you log this week, from the table or on its own, drops its star into the jar at the top of My workouts, and the jar fills up toward your weekly goal (tap it to change the goal). Reach the goal and the jar glows. The small jar next to it counts how many weeks in a row you filled it.",
    faq_q_sport_workout_jar: "What are the colored stars and the jar in My workouts?",
    faq_a_sport_workout_gcal: "Yes – in ⋯ → Google Calendar (once Google Calendar is connected in Settings). Every workout with a time becomes a weekly repeating event on its days, and changes in the app update it. Reminders come only from the app, so Google adds none of its own, and the workouts never show up twice in the app. Tapping it again removes only the workouts from Google Calendar.",
    faq_q_sport_workout_gcal: "Can my workouts appear in Google Calendar?",
    workout_gcal_btn: "Google Calendar",
    workout_gcal_error: "Google Calendar could not be updated – it will try again with the next change",
    workout_gcal_not_connected: "Connect Google Calendar in Settings first",
    workout_gcal_off_toast: "The workouts were removed from Google Calendar",
    workout_gcal_on_toast: "Your workouts are in Google Calendar",
    faq_a_sport_workout_reminder: "Yes – in a workout, Reminder: 10 minutes, 30 minutes or an hour before, or a custom time (the workout needs a time). It rings like your other reminders, once and in one place: in the app if it is open, otherwise on your phone. \"Done\" logs the workout in the history, and \"Not yet\" reminds again in 5 minutes.",
    faq_q_sport_workout_reminder: "Can I get a reminder before a workout?",
    workout_reminder_30min: "30 minutes before",
    workout_reminder_label: "Reminder",
    workout_reminder_need_time: "Add a time to get a reminder",
    faq_a_sport_workout_share: "In ⋯ → Share, the week becomes a glassy image in your theme colors, with a gentle link to the app (on a phone it goes straight to the share sheet, on a computer the image is saved). ⋯ → PDF to print opens a clean page of the whole week, with a box to tick next to every workout and exercise – choose \"Save as PDF\" or print it. The plan also appears in the data report in Settings, under Sport.",
    faq_q_sport_workout_share: "How do I share or print my workout week?",
    share_image_saved: "The image is saved – you can attach it",
    share_save_image: "Save the image",
    workout_pdf_btn: "PDF to print",
    workout_share_btn: "Share",
    faq_a_sport_workout_board: "In ⋯ → Weekly board, every day is a column: drag a workout to another day (on a phone, press and hold first). In a workout, \"Also in My Routine\" puts it in your routine at its time and days, and changes stay in sync both ways; from an item in My Routine, \"Add to my workouts\" does the opposite. A ✓ in either place counts in both, and in My Day it shows once – in the chip next to the water.",
    faq_q_sport_workout_board: "How do I move a workout to another day, and link it to My Routine?",
    routine_in_workouts_btn: "Open in my workouts",
    routine_to_workout_btn: "Add to my workouts",
    routine_to_workout_done: "Added to my workouts 💪",
    workout_delete_confirm_routine: "It will be removed from the plan and from My Routine. Workouts already logged in your history stay.",
    workout_moved: "Moved to {day}",
    workout_routine_need_time: "Add a time to put it in My Routine",
    workout_routine_toggle: "Also in My Routine",
    workout_view_board: "Weekly board",
    workout_view_timeline: "Timeline",
    faq_a_sport_workout_plan: "In Workout Tracking, under \"My workouts\": + Workout – type, days, time, duration, intensity and place (also \"Other\"). Strength, functional and swimming workouts can hold a list of exercises, and Rest marks a rest day. You can also start from a ready plan. Today's workout shows big, with the whole week under it; ✓ logs it in the workout history together with its intensity. In ⋯ you set a weekly goal (workouts or minutes) – every workout you do drops its star into the jar.",
    faq_a_sport_workout_today: "In My Day, next to the water, a small chip shows today's workout – a tap opens the details, ✓ and ▶. ▶ starts a timer that keeps running in the chip on the home screen, and \"Finish\" logs the workout with the real time. If the \"Two weeks of movement\" challenge in New Me is running, a logged workout counts in it by itself.",
    faq_q_sport_workout_plan: "How do I plan my workout week?",
