    dictation_service_off: "Dictation is turned off in this browser or computer – turn it on in the computer settings, or try Chrome",
    faq_a_new_me_magic_themes: "Five sparkly themes that come with New Me: Enchanted Forest, Stardust, Rose Fairy, Magic Aurora and Golden Dusk. Choose one inside New Me (⚙️ Settings > Colors) or in Settings > Appearance & Display, and a sparkly brush paints the screen in it. A magical theme adds sparkles across the whole app and at every tap. You can switch back to any other theme anytime.",
    faq_q_new_me_magic_themes: "What are the New Me magical themes?",
