    quotes_look_wall: "Wall",
    theme_magic_section_label: "New Me magical themes",
    apptour_focus_text: "Everything steps aside except the one thing for now – with a big ✓. Then the next one shows up.",
    apptour_m_presets_text: "Your saved meals in one place: search, recently used, by time of day – and ＋ adds one to today.",
    apptour_night_text: "🌙 turns the whole app dark; ☀️ brings the day back.",
    apptour_noteline_text: "Write and tap ➤ – it's saved in your notes. 📝 at the start switches to 🛒 shopping or 🍎 a saved meal.",
    apptour_search_text: "Notes, shopping, calendar, recipes, notebooks, goals, tables and books – one search finds it all.",
    faq_a_new_me_ai_menu: "Before the menu, the questionnaire asks which meals you eat and when (2 meals + a snack, 2 meals + a light dinner, or both), whether you have something small in the evening and at what time, what you don't eat, and how you drink coffee or tea. AI then builds 3 options for every meal – each sized to that meal's share of the day, so the day still adds up to exactly 1,300 or 1,500 – plus drink ideas, which are saved as your fixed drinks. Pick up to 2 favorites per meal; the original menu options are right under them, and in 🔄 Swap they come after your personal menu. 🔄 Other options builds a new set (3 times per questionnaire). To change your answers or build a new menu anytime: ⚙️ Settings → ✨ Personal menu (AI).",
    faq_q_new_me_ai_menu: "How does the personal New Me menu work?",
    nm_ai_menu_building: "Building a menu for your meals and times…",
    nm_ai_menu_drinks: "Drinks for you",
    nm_ai_menu_error: "The personal menu couldn't be built right now – here's the original menu. You can try again, or later from ⚙️ Settings.",
