    apptour_later: "Not now",
    apptour_resume: "Continue where I stopped",
    apptour_s_gcal_inside_text: "Connect Google Calendar once, and events and tasks stay in sync both ways.",
    apptour_s_menu_text: "Everything you can adjust lives here, in five groups. Let's open them 👇",
    apptour_skip_part: "Skip this part",
    apptour_start: "Start the tour",
    nm_sales_premium: "Includes all of Premium",
    nm_unlock_premium: "All of Premium is unlocked too.",
    settings_sub_status_newme: "Premium is included in your New Me.",
    room_back_to_shelf: "To the shelf",
    faq_a_new_me_day_total: "Every day adds up to the plan exactly: the meals, about 150 calories for coffee and drinks during the day, and whatever was chosen for the evening – something small to eat or something to drink. For the evening, pick up to 3 you like (for example a banana, a yogurt or 2 squares of dark chocolate; or herbal tea, tea with a little milk or warm milk), and their calories are taken from the meals. Every choice balances itself: a smaller or bigger option, a meal left out, the small breakfast and the small meal that comes with it, or the evening – the difference is added to or taken from the meals, each by its size, and under each meal it says how much (+ or −) and what to add or leave out. A meal that was already checked stays as it was logged. In the questionnaire, each meal shows its fix, and a small box shows meals, drinks, the evening and the total. Feel like something else that day? Keep the total at the same calories or less.",
    faq_q_new_me_day_total: "How does a New Me day add up to exactly 1,300 / 1,500, and where do drinks count?",
    nm_budget_chosen: "Chosen menu ~{n} · {adj} in the meals",
    nm_budget_drinks: "Coffee & drinks",
    nm_budget_drinks_drink: "Coffee & drinks, {time} too",
