    nm_budget_meals: "Meals",
    nm_budget_total: "Total for the day",
    nm_extra_line_fill: "{n} calories for this meal, so the day adds up to {plan} – e.g. {ideas}",
    nm_less_ideas_l: "a slice of bread and a tablespoon of tahini less, or half the carbs",
    nm_less_ideas_m: "one slice of bread less, or a tablespoon less tahini",
    nm_less_ideas_s: "a teaspoon less oil or tahini",
    nm_less_line: "{n} calories in this meal, so the day adds up to {plan} – e.g. {ideas}",
    nm_less_line_late: "{n} calories in this meal, for something small at {time} – e.g. {ideas}",
    nm_swap_balanced: "{n} calories spread across the meals, so the day adds up to {plan}",
    books_quotes_chip: "Quotes",
    faq_a_book_quotes: "On the shelf in the secret room (Quotes), or with the small 💬 Quotes chip in the Reading Corner – it's the same list. Tap \"+ Quote\", write the line and pick the book from your Reading Corner, or type another title with \"✏️ Other\"; the author is optional. ✏️ edits a quote and 🗑️ deletes it. The quotes are bookmarks you swipe through – 🎨 at the top switches to photos or a wall of cards.",
    faq_a_room_wish_jar: "On the shelf in the secret room there's a glass jar for dreams. Tap the little jar on the top shelf (or Shelf > The wish jar) and write how you'd like your life to look – as wild as you like, no right or wrong. Each wish is folded into a note and dropped into the jar. \"Pull out a note\" opens a random one, and every note can also be opened on its own. From the second time you open the same wish, you can make it a goal and break it into small steps. Once a week a gentle note with one of your wishes pops up – no pressure, just a reminder of where you're heading.",
    faq_q_book_quotes: "Where do I keep quotes from books I loved?",
    faq_q_room_wish_jar: "What is the wish jar in the secret room?",
