    room_wish_written: "Written on {date}",
    faq_a_saved_meals_page: "Saved meals have a page of their own: Nutrition & Metrics > ⭐ Saved meals (or ⭐ in the menu). The search at the top finds a meal by name or ingredient, \"Recently used\" shows what you added lately, and the tabs (Breakfast, Lunch, Dinner, Soups…) show each time of day. \"+ Today\" adds a meal to today's Daily Meal Tracker, in the next free slot. Tap a meal to edit or delete it, and ＋ at the top adds a new one.",
    faq_q_saved_meals_page: "Where do I find and manage my saved meals?",
    preset_edit_title: "Edit meal",
    presets_add_today_btn: "+ Today",
    presets_add_today_long: "Add to today",
    presets_delete_btn: "Delete meal",
    presets_delete_confirm: "\"{name}\" will be removed from your saved meals. Whatever you already logged stays.",
    presets_delete_title: "Delete this meal?",
    presets_new_btn: "+ New meal",
    presets_no_results: "No saved meal like that",
    presets_recent_label: "Recently used",
    presets_search_placeholder: "Which meal?",
    presets_tab_all: "All",
    presets_tab_dessert: "Desserts",
    presets_tab_drinks: "Drinks",
    presets_tab_evening: "Dinner",
    presets_tab_morning: "Breakfast",
    presets_tab_noon: "Lunch",
    presets_tab_snack: "Snacks",
    presets_tab_soup: "Soups",
    presets_tab_sweet: "Sweets",
    faq_a_notes_sticky_look: "Notes are a short list of glass cards – 🎨 at the top of Notes changes the look of all of Notes: the list, the day buttons at the top and the window where a note is written – glass, clean list, index cards or washi tape. A note being dragged keeps exactly its own look and color. Tap a note's text to open it – there you can edit it, change its colors and see when it was last written. Tap ○ when it's done, and × moves it to the archive (🗑️ at the bottom of the list brings it back). Drag it by ⠿ to change the order, below \"Get to it\", or onto a day at the top. ! marks a note as urgent – it glides gently up to the first rows with a small “Urgent” tag; another tap takes it off.",
    faq_q_notes_sticky_look: "How do I open, edit or remove a note?",
    note_to_archive_btn: "Move to archive",
    faq_a_routine_clash: "If there's already an item at that time on the same days, you get two choices: \"Replace\" – the new item takes that time and you pick a time for the one that was there (when editing an item, its previous time is suggested, so the two simply swap), or \"Both\" – they both stay at the same time, one under the other. If the days are different (say one is Sun–Thu and the other Friday), nothing is asked at all.",
    faq_q_routine_clash: "What happens when I put a routine item at a time that's already taken?",
    routine_clash_both: "✌️ Both – keep them both at {time}",
    routine_clash_move_btn: "Move and save",
    routine_clash_move_to: "What time should \"{title}\" move to?",
    routine_clash_replace: "🔄 Replace – and move \"{title}\" to another time",
    routine_clash_title: "At {time} there's already: {title}",
    faq_a_new_me_coffee: "Under today's menu there's a short summary: how many calories all of today's meals add up to, how much is left for coffee and drinks, and buttons for the coffee and drinks that were picked – one tap adds it to Drinks. In \"Pick up to 3 you like\" under the buttons (and in the questionnaire) choose what shows: water / soda water, herbal tea, a diet drink, black / americano (~5), tea with a little milk (~25), water-based coffee with up to 100 ml of milk or plant milk (~50), light hot chocolate, warm milk or regular coffee / latte (~120).",
    faq_q_new_me_coffee: "Where do I add coffee, and how do I know how much is left for the day?",
    nm_coffee_black: "Black / americano, no milk",
    nm_coffee_regular: "Regular coffee / latte",
    nm_coffee_title: "Coffee",
