    nm_late_ideas_none: "Very little is left today – tea, water or black coffee",
    nm_late_room_line: "Something small before bed · ~{n} kcal left today",
    faq_a_recipe_examples: "Under your own recipes there are example recipes: breakfasts, salads, soups, mains, sides, snacks, desserts and vegan dishes, each with the prep time, the calories per serving and how many grams one serving weighs. Tap a recipe to open it, and \"Save to My Recipes\" makes your own copy that you can edit. The category chips filter, and tapping the same chip again shows everything.",
    faq_a_recipe_grams: "Inside a recipe, next to the calories, it says \"1 serving ≈ X g\". For your own recipes, fill in \"Grams per serving\" (and the prep time, if you like) in the recipe form: both are optional, and the time shows up on the recipe's color band.",
    faq_q_recipe_examples: "What are the example recipes in My Recipes?",
    faq_q_recipe_grams: "How do I see how many grams one serving is?",
    recipe_category_vegan: "Vegan",
    recipe_grams_placeholder: "Grams per serving",
    recipe_meta_grams: "1 serving ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} min",
    recipe_minutes_placeholder: "Prep time (minutes)",
    recipe_save_example_btn: "Save to My Recipes",
    recipe_saved_example: "✓ Saved in My Recipes",
    recipe_saved_example_toast: "Saved in My Recipes – you can edit it there",
    recipes_examples_title: "Example recipes",
    faq_a_recipe_scan_multi: "Yes. In \"Add Recipe\", tap 📷 and pick one photo or several (up to 6; a PDF works too). Each one shows up in a short list where you choose what's in it: All, Ingredients or Steps, and \"➕ Another photo\" adds more. Then tap \"✨ Scan the recipe\": the AI puts everything together into one recipe, in order and without repeated lines, and it counts as a single scan. Several photos picked from 📷 Photo in the AI assistant open here too.",
    faq_q_recipe_scan_multi: "Can I scan one recipe from several photos, like the ingredients and the steps separately, or two pages?",
    recipe_scan_add_more: "➕ Another photo",
    recipe_scan_part_all: "All",
    recipe_scan_part_ingredients: "Ingredients",
    recipe_scan_part_steps: "Steps",
    recipe_scan_remove_photo: "Remove photo",
    recipe_scan_run_btn: "✨ Scan the recipe",
    recipe_scan_too_many: "Up to {n} photos per recipe",
    faq_a_note_written_at: "Tap the note's text to open it. Inside, under the text, you'll see when it was last written, with the exact date and time. Only a change to the text itself updates it: archiving and restoring, ticking ✓, colors or moving the note around don't change it.",
    faq_q_note_written_at: "How can I see when I wrote a note?",
    note_written_at: "Last written: {date}",
    faq_a_new_me_month: "In the magic bag → Monthly calendar: each day is colored by how many meals were ticked, the ‹ › arrows move between months, and under the calendar is the month's average calories per day. A tap on a day shows how many meals were ticked and how many calories were eaten that day.",
    faq_q_new_me_month: "Where can I look back over the month and see my average calories in New Me?",
    nm_month_avg: "Month average: {kcal} calories a day · days logged: {n}",
    nm_month_day_empty: "Nothing logged on this day.",
    nm_month_day_line: "Meals ticked: {checks} · calories: {kcal}",
    nm_extra_line_small: "{n} calories for this meal, from the small breakfast – e.g. {ideas}",
    faq_a_new_me_small_breakfast: "A light breakfast (about 170 kcal): a spelt pita (up to 100 kcal) with a spread or cheese, plus a vegetable – pick up to 3 you like, for example 1 tsp chocolate spread, 1 tsp peanut butter or a slice of hard cheese (up to 22%). Because it's small, \"Plus a small meal\" comes with it at another time (an hour and a half later, for example 11:30 → 13:00 – any other time can be picked): another pita & spread, protein yogurt & fruit, rice cakes & cheese, cereal & milk or half a pita & eggs – up to about 200 kcal, with its own ✓. Whatever is still left is shared by the other meals, and each meal shows how much was added, so the day's total stays as planned. Pick it in the questionnaire, or switch to it for today only with 🔄 – for example when breakfast is late.",
    faq_q_new_me_small_breakfast: "What is the \"small breakfast\" in the New Me menu?",
    home_note_meal_ai: "✨ Work it out with AI",
    home_note_meal_none: "No saved meal like that",
    myday_earlier: "Earlier",
    nm_ing_spelt_pita: "Spelt pitas",
    nm_ing_spread: "Spread (chocolate / peanut butter / raw tahini)",
    weather_now: "Outside now: {sky}",
    weather_sky_clear: "Clear",
    weather_sky_clouds: "Cloudy",
    weather_sky_fog: "Fog",
    weather_sky_partly: "Partly cloudy",
    weather_sky_rain: "Rain",
    weather_sky_snow: "Snow",
    weather_sky_storm: "Storm",
    faq_a_ai_icon: "Yes – in Settings > Appearance & Display. The soft bubble is the default, and with Premium you can also choose a floating brain or a robot.",
    faq_a_new_me_favorites: "Yes. In the questionnaire (and when retaking it from the settings), you can choose up to 2 options for each meal. The first one is shown in the menu, with an \"or\" line under it for the second – a tap on it switches to it for today only. And if breakfast wasn't eaten on time, \"⏰ Later\" moves it to later in the day without changing the calories.",
    faq_a_theme_mode: "Some special themes look their best dark – Watercolor, Aurora Borealis, Barbie and the two Sparkle themes – so picking one of them switches the app to dark mode, and picking any other theme (the rocket too) switches it to light. Black and Dark Grey stay dark. You can always change it afterwards with 🌙 in the menu or with Light Mode in settings.",
    faq_a_water_month: "In water tracking. Every entry in today's log shows the time it was added, and \"Monthly table\" opens the whole month: each day shows how many liters were drunk (✓ when the daily goal was reached), and a tap on a day shows its entries with their times.",
    faq_q_ai_icon: "Can I change the AI assistant's icon?",
    faq_q_new_me_favorites: "Can I choose two favorite options for a meal in New Me?",
    faq_q_theme_mode: "Why did the app turn dark (or light) when I picked a theme?",
    faq_q_water_month: "Where can I see how much water I drank each day?",
