    ai_chat_working_table: "One moment, building the table…",
    faq_a_ai_chat: "Tap the bubble and a chat opens. Choose what to do – something for the calendar, what you ate, a recipe photo or a new table – or just write, and the assistant figures it out. You can also tap 🎙️ and speak instead of typing. For the calendar you can choose once, every week or every day. The answer arrives in the chat, and from there you can go on to something else or open the calendar / what you ate.",
    faq_q_ai_chat: "How do I talk to the assistant?",
    nm_backpack: "The magic bag – all of New Me",
    nm_door_label: "Door {n}",
    nm_hall_next: "Next · {slot}",
    nm_hatch_climb: "Climb to the roof",
    nm_hatch_label: "The hatch to the roof",
    nm_keys_tip: "Every challenge that ends, of any length, opens a door. It's worth choosing a challenge you really want to succeed at.",
    nm_tour_bag_text: "Everything is in the bag: the map, achievements, shopping and settings.",
    nm_tour_bag_title: "The magic bag",
    faq_a_new_me_routine_meals: "When meals are set in New Me and My Routine has meals too, New Me asks whether to hide them and show the New Me meals in their place – so nothing shows twice. My Routine then shows the New Me meals at their times, with 💎 and a ✓; tapping a meal's name opens a window to choose another meal or change its time, right there over the routine. Nothing is deleted: they come back from New Me's ⚙️ Settings → Meals in the routine, or by turning off \"Sync with New Me\" in My Routine's ⚙️. Without an active New Me they come back by themselves.",
    faq_q_new_me_routine_meals: "Why does My Routine show the New Me meals?",
    nm_routine_hidden_toast: "My Routine now shows the New Me meals 💎",
    nm_routine_hide: "Hide from the routine",
