    recipe_to_shopping_btn: "{n} to the shopping list",
    recipes_filter_all: "All",
    recipes_new_tile: "New recipe",
    recipes_new_tile_sub: "or paste one from a website",
    recipes_no_results: "No recipe found",
    recipes_scan_title: "Scan a recipe",
    recipes_search_placeholder: "Search a recipe or ingredient…",
    dictation_btn_aria: "Speak and it's written",
    dictation_mic_denied: "The microphone is blocked – allow it from the 🔒 next to the address bar, or in the phone settings",
    faq_a_dictation: "Yes – tap the 🎤 microphone in the corner of the quick note or a notebook writing page, and speak: the words are written as you talk, in the app's language. Tap it again to stop. The first time, the browser asks for permission to use the microphone. Works in Chrome / Android and in Safari on iPhone. On a computer you need a microphone and a browser like Chrome, Edge or Safari – if something is missing, the message says exactly what.",
    faq_q_dictation: "Can I speak instead of typing?",
    faq_a_secret_room: "A room that's only yours, inside New Me – a house inside a giant tree. You see one wall at a time and turn with the arrows (or a swipe). The first key comes after a ✓ on a meal on 3 different days and opens the door – and the whole room with it: the computer, the game, the record player, the shelf with the library inside and the cat. Then every challenge that ends (the challenge of the week too) gives a key that opens the next place: the star roof, the porch by the sea, the guitar and the diary, the breathing room, the forest path with yoga, the waterfall and a surprise on the roof – and the 8th brings a bottle from the sea, with the letter from the past inside. When something opens, an arrow shows the way to it. The little door at the bottom of the game machine opens too – for now the cabinet behind it is empty. On the star roof, a tapped star falls like a shooting star, and the cat sits on the cushion.",
    faq_q_secret_room: "What is the secret room in New Me?",
