    home_countdown_tomorrow: "Tomorrow · {title}",
    home_streak_days: "{n} days in a row",
    home_streak_title: "Days in a row with at least one ✓",
    settings_good_things_label: "\"3 good things\" in the evening",
    settings_weather_hint: "Rain, clouds or snow in the home screen background, by the weather where you are. Your approximate location stays on this device and is checked through our server with MET Norway.",
    settings_weather_label: "Weather in the home screen sky",
    weather_failed: "Couldn't check the weather right now.",
    weather_location_denied: "No access to your location – allow it in the browser settings and try again.",
    faq_a_home_focus: "Tap ◎ at the top of the home screen: everything disappears except the one thing for now – what's on at this hour, or the next thing on today's list – with a big ✓, plus Quick Note. After the ✓, the next thing shows up. Tap 'Focus mode ✕' at the top to bring everything back.",
    faq_a_home_search: "Open the menu ☰ – the search is right at the top. Type at least 2 letters: results come from your notes, shopping list, calendar, recipes, notebooks (titles and page text), goals, tables and books, grouped by type – tap one to jump straight there.",
    faq_a_my_day: "My Day brings together what used to be A Peek at Today and My Routine, on one timeline. At the bottom of the home screen you see how much is done, what's now or next (with a quick ✓) and, next to the title, a +1 glass of water. Tap it (or swipe it up) to open the whole day: things with no set time at the top, then everything by the hour – calendar tasks, events and meetings, weekly fixed slots, today's routine, your goals' small steps and New Me meals – with a line for now. Filter by Tasks, Routine or Meetings & events. A ✓ here is the same ✓ everywhere else (My Routine, My Goals, the calendar) and opens a daisy in the corner. 'Edit my routine' opens My Routine (it's also in the menu), and '＋ Add for today' adds a task for today. A tap on the \"My Day\" title (or the little bar at the top) closes it again.",
    faq_q_home_focus: "What is focus mode?",
    faq_q_home_search: "How do I search the whole app?",
    faq_q_my_day: "What's in My Day at the bottom of the home screen?",
