    nm_plan_life_sub: "One payment – yours for good",
    nm_plan_life: "Lifetime",
    faq_a_new_me_tour: "Right after buying and filling in the short questionnaire, a short tour shows the game: the top bar, the next mission, the challenge of the week, the magic bag and door 1 to the secret room. It can be replayed anytime from ⚙️ Settings > 🧭 New Me tour – the full name from the questionnaire can be changed there too. Before buying, New Me shows a 🔒 in the menu, and tapping it opens a page with everything that's included.",
    faq_q_new_me_tour: "Is there a guide to New Me?",
    nm_locked_label: "locked – tap to see what's included",
    nm_settings_tour: "New Me tour",
    nm_tour_done_text: "The tour can be replayed anytime from ⚙️ Settings.",
