    nm_tour_tiles_text: "The journey and achievements, shopping list, measurements, photos, monthly calendar, reminders and the menu PDF.",
    nm_tour_tiles_title: "Everything else",
    nm_tour_challenges_text: "20 challenges to choose from, started whenever you decide – and a gift waits at the end.",
