    nm_tour_swap_text: "🔄 swaps a meal – from the menu, the saved meals or written with AI, for today or from now on. ⭐ saves it, ➖ removes it from the menu.",
    nm_tour_menu_text: "Today's meals. A ✓ when a meal is eaten – it's added to the Daily Meal Tracker by itself.",
    nm_tour_ring_text: "The ring shows how much is left from the plan today. Workouts add to it.",
    nm_tour_ring_title: "Calories left today",
    nm_tour_welcome_text: "A quick look at the game – it takes less than a minute.",
