    nm_sales_a3: "It's a general menu, not medical advice. A medical disclaimer is shown before starting, and it's worth checking with a health professional first.",
    nm_sales_q3: "Is it right for me?",
    nm_sales_a2: "No – New Me is a separate program, and it includes all of Premium.",
