    nm_gift_locked_view: "The gift opens after all {n} challenges – {left} to go.",
    nm_gift_intro: "All {n} challenges, step after step. Here's what was waiting:",
    nm_gift_title: "Your gift",
    faq_a_new_me_letter_gift: "At the start of New Me (or later, in Challenges) a letter to yourself in the future can be written. Once sealed, it can't be read or edited until it opens: in the bottle from the sea in the secret room, or at the end of all 20 challenges – where a gift waits too.",
    faq_q_new_me_letter_gift: "What is the letter from the past?",
    faq_a_new_me_challenges: "🏆 Challenges has 20 challenges: 10 big ones (like 5 days without sugar, a week without carbs, or losing 4 kg in a month – a calorie deficit, a workout and no sugar every day) and 10 mini ones – small habits for a week, like cinnamon coffee without sugar. Picking a challenge asks when to start: today, tomorrow, next week or another date. One big and one mini challenge can run at the same time. A running challenge shows at the top of the menu and in My Day, with a ✓ for the day. Each week of a challenge comes with one free day (🍕) that doesn't break it, and a day that isn't marked counts as a free day – today and yesterday can be marked. Some days mark themselves: a 20-minute workout in Workout Tracking, or the menu meals with ✓. Each challenge has an ⓘ with what exactly counts (for example, the full list of carbs) – in the challenge itself and next to it in My Day. Below them, 🌱 Personal growth has 48 small challenges for one week (they don't count toward the 20) – see “What is the challenge of the week?”.",
    faq_q_new_me_challenges: "How do the challenges in New Me work?",
    nm_letter_too_short: "A few more words 🙂",
    nm_letter_quiz_note: "Optional – it can also be written later, in Challenges.",
    nm_letter_write: "✍️ Write the letter",
    nm_letter_sealed_line: "Sealed on {date} · opens after the {n} challenges",
