    nm_ch_cinnamon_coffee_desc: "Every morning: coffee with a pinch of cinnamon and no sugar – a gentle sweetness with no calories.",
    nm_ch_cinnamon_coffee_title: "Cinnamon coffee, no sugar",
    nm_ch_lose5_month_task: "Deficit + workout + no sugar",
    nm_ch_lose5_month_desc: "Three things every day: staying within the calorie budget (a deficit), a workout, and no added sugar. The days count – not the scale, which moves at its own pace.",
    nm_ch_lose5_month_title: "Lose 4 kg in a month",
    nm_ch_menu_21_task: "Meals from the menu ✓",
    nm_ch_menu_21_desc: "Every day the menu meals get ✓ – at least 3, or all of them when the menu is smaller. A planned free meal counts, and the day is marked by itself.",
    nm_ch_menu_21_title: "21 days on the menu",
    nm_ch_no_sugar_21_desc: "Three weeks without added sugar – enough time for the cravings to calm down. Fruit and natural sweetness are welcome.",
    nm_ch_no_sugar_21_title: "21 days without sugar",
    nm_ch_no_snacking_14_task: "Only what's on the menu",
    nm_ch_no_snacking_14_desc: "Only what's on the menu and the drinks – no nibbling in between. Feeling hungry? A glass of water or tea, and the next meal is close.",
    nm_ch_no_snacking_14_title: "Two weeks without extra snacking",
    nm_ch_home_food_14_task: "Home-made food today",
    nm_ch_home_food_14_desc: "No deliveries or takeaway – something made at home, even something simple. A planned free meal is allowed.",
    nm_ch_home_food_14_title: "Two weeks of home cooking",
    nm_ch_no_fried_14_task: "A day without fried food",
    nm_ch_no_fried_14_desc: "No fries, fried schnitzel or deep-fried snacks – baking, grilling or the air fryer instead.",
    nm_ch_no_fried_14_title: "Two weeks without fried food",
    nm_ch_sport_14_task: "20 minutes of movement",
    nm_ch_sport_14_desc: "At least 20 minutes of activity a day – a walk counts too. A workout logged in Workout Tracking marks the day by itself.",
    nm_ch_sport_14_title: "Two weeks of movement",
    nm_ch_deficit_14_task: "Within the calorie budget",
