    nm_tile_challenges: "Challenges",
    faq_a_workout_calories: "Yes. Every workout gets an estimate of the calories burned – by type, duration and your latest weight (for running and cycling also by speed, when a distance is entered). It shows in the workout list and in the monthly summary (Burned), and it's added to that day's calorie budget: in the Daily Meal Tracker, in Calorie & Weight Metrics and in New Me's ring. It's an estimate, so it's shown with ~.",
    faq_q_workout_calories: "Do workouts count in my daily calories?",
    faq_a_new_me_flexible_menu: "Yes. In the questionnaire and in settings, choose how many meals a day – 2 meals + a snack / 2 meals + a light dinner / 2 meals + a snack + a light dinner – and ➖ on a meal card removes it (at least 3 stay); '➕ Add back' returns it. Either way the day's calories stay the same: what's left out is shared by the other meals, and each meal shows how much was added and what could go with it. ✏️ Edit on a meal opens its text – change what you like (e.g. no bread, or one more egg) and AI works out the calories and protein again. 🔄 Swap offers options from the menu, ⭐ Saved meals and ✨ Write it; every change can be for today only or from now on. At the end of 'The whole day' there's ➕ Add food – write what was eaten outside the menu, and AI works it out and adds it to today (✕ removes it).",
    faq_q_new_me_flexible_menu: "Can I change the number of meals in New Me, or eat my own meal?",
    daily_calorie_mini_burn: "+🔥 {amount} from workouts",
    calorie_burn_line: "🏃 {amount} kcal from workouts – added to the day's budget ({budget})",
    sport_total_kcal: "Burned",
    nm_swap_ai_too_big: "A bit more than what’s left for today – up to ~{n} kcal fits. You can still log it – the rest of today’s meals get smaller to balance – or pick a smaller portion.",
    nm_swap_ai_use: "Use this meal",
    nm_swap_ai_rough: "rough estimate",
    nm_swap_ai_busy: "Estimating…",
    nm_swap_ai_go: "✨ Estimate",
