    nm_swap_ai_hint: "Write what you'd like to eat, with amounts if possible – the calories and protein are estimated for you.",
    nm_swap_saved_empty: "No saved meals yet – they're added in the Daily Meal Tracker (⭐ / 💾)",
    nm_swap_bigger_label: "Bigger than today's budget",
    nm_swap_saved_none_fit: "None of the saved meals fits today's budget",
    nm_swap_budget: "Fits today: up to ~{n} kcal",
