    vision_focus_ribbon: "🎯 Goal of the month",
    vision_tagline: "Big goals, small steps.",
    faq_a_app_tour: "The tour opens automatically once, the first time you enter. It starts with its parts – tap one to jump straight to it – then shows every part of the app (the home screen, the AI assistant and every item in the menu) and the five groups of Settings, each with a short explanation, and peeks inside some of them (for example, a sample goal path, the bag and Google Calendar). Continue moves on, Back goes back, Skip this part jumps to the next part and ✕ closes the tour. You can replay it anytime from Settings > Help & Usage > App Tour, and continue from where you stopped. Continue and Back always stay in the same place at the bottom of the screen, and on a computer the arrow keys work too.",
    faq_q_app_tour: "How do I see the app tour again?",
    apptour_done_text: "Any question? Help & FAQ in Settings answers everything, and this tour is always there under Help & Usage.",
    apptour_done_title: "That's everything! 🎉",
    apptour_flow_recurring: "Installments & standing orders",
    apptour_flow_weight: "Weight",
    apptour_flow_calories: "Today's calories",
    apptour_flow_calendar: "Calendar",
    apptour_connect_text: "What you do in one place updates the others automatically:",
    apptour_connect_title: "Everything is connected",
    apptour_s_support_text: "Help & FAQ, contact us, sharing the app – and this tour, anytime.",
    apptour_s_account_text: "Premium, password, a personal PDF report, Google Calendar sync and account deletion.",
    apptour_s_notifications_text: "Reminder notifications and their sound. '⏰ Not yet' on a reminder works like a snooze: it reminds again every 5 minutes.",
    apptour_s_personalization_text: "Country, meals and snacks per day, when your financial month starts, and what shows on the home screen.",
    apptour_s_appearance_text: "Language, light or dark mode, themes, font, text color, accessibility and app size.",
    apptour_m_style_text: "This button switches the menu to big tiles – and back. Only one of them appears on the home screen.",
    apptour_m_style_title: "List or tiles",
    apptour_m_receipts_link: "Export a category as a PDF, or total everything by years with 🧮.",
    apptour_m_receipts_text: "Keep tax invoices and receipts with photos, for home or business.",
    apptour_m_budget_link: "Installments and standing orders (with Excel import), your own categories and a budget reset day in Settings.",
    apptour_m_budget_text: "Expenses and income by category, with a monthly balance.",
    apptour_m_steps_text: "Your daily step count.",
    apptour_m_sport_link: "Habits in My Routine can log workouts here automatically.",
    apptour_m_sport_text: "A weekly workout plan, and logging workouts by type, time and distance – even with a photo.",
    apptour_m_water_text: "Track how much water you drink against a daily goal.",
    apptour_m_calories_link: "Weight tracking lives here too – shared with New Me and with weight goals in My Goals.",
    apptour_m_calories_text: "Daily, weekly and monthly calorie stats against your goals.",
    apptour_m_meals_link: "Saved meals, a food list and AI estimates; New Me, quick adds and drinks count here too.",
    apptour_m_meals_text: "Log each meal with calories and protein, day by day.",
    apptour_m_recipes_link: "Scan a written recipe with 📷 Photo in the AI assistant.",
    apptour_m_recipes_text: "Your recipes by category, with photos, calories and servings.",
    apptour_m_goal_link: "Can follow your weight or completed tasks automatically.",
    apptour_m_goal_text: "One goal for the month, with a progress bar and a reward when you reach it.",
    apptour_m_shopping_link: "Add items from Quick Note in a second.",
    apptour_m_shopping_text: "Your shopping list – check items off at the store.",
    apptour_m_notes_link: "Drag a note to Today, Tomorrow or another date to turn it into a task; deleted notes wait in the 🗑️ archive.",
    apptour_m_notes_text: "Notes and ideas in one list.",
    apptour_m_tables_link: "The AI assistant can design a table automatically.",
    apptour_m_tables_text: "Personal tables – gifts, series, lists – with text, number, choice, date and ✓ columns (Premium).",
    apptour_m_study_link: "🪄 Smart Split, inside the ✅ Tasks card, breaks a big task into steps on your calendar.",
    apptour_m_study_text: "Your bag: a pocket for every part of life – with notebooks, tables and tasks inside.",
    apptour_m_vision_link: "📅 on a station puts it in the calendar; small steps and a days challenge's tasks show up in My Day, and progress can also follow a number or your weight.",
    apptour_m_vision_text: "Your goals as paths of small steps – with today's steps up top. Let's peek inside 👇",
    apptour_m_myweek_link: "Syncs with Google Calendar (in Settings).",
    apptour_m_myweek_text: "The monthly calendar, recurring weekly tasks with reminders, all your dated events, and a paper diary of the week's meetings 🤝.",
    apptour_m_newme_link: "Everything counts in the Daily Meal Tracker and My Day; weight is shared with Calorie & Weight Metrics.",
    apptour_m_newme_text: "A 1,300 / 1,500 calorie meal plan inside a magical game world: today’s menu with ✓, swaps three ways – from the menu, from your saved meals, or by writing to the AI what you ate, and it works out the calories – a shopping list, meal reminders and a progress journey with achievements, measurements and photos. Plus 🏆 20 challenges – with a gift at the end – and a challenge of the week.",
    apptour_ai_table_text: "Describe the table you need – the AI designs its columns (Premium).",
    apptour_ai_photo_link: "Saved in My Recipes.",
    apptour_ai_photo_text: "Snap a written recipe – the AI fills in a new recipe for you.",
    apptour_ai_schedule_link: "They appear in the calendar and in My Day.",
    apptour_ai_schedule_text: "Describe plans in plain words, one-time or recurring – they go straight into the calendar.",
    apptour_ai_food_link: "Goes straight into the Daily Meal Tracker and today's total.",
    apptour_ai_food_text: "Type what you ate – the calories are estimated and logged for you.",
    apptour_newme_short_text: "Opens New Me – today's menu is right on the main screen.",
    apptour_ai_link: "A small 1 badge on it is the daily 'what matters today' reminder.",
    apptour_ai_text: "Write in plain words and your assistant does the rest: logs calories, puts plans in your calendar, reads a recipe from a photo and builds tables.",
    apptour_quicknote_link: "📝 and 🛒 open the full lists; 🍎 logs a saved meal in the Daily Meal Tracker.",
    apptour_quicknote_text: "Write something down fast – into your Notes or straight onto the Shopping List.",
    apptour_routine_link: "A habit can log a workout in Workout Tracking automatically.",
    apptour_routine_text: "Your daily routine by the hour, in tabs (kids, study, work…). Tick ✓ every day to build habits and streaks; 📅 shows the whole month.",
    apptour_premium_text: "Unlocks the full AI assistant, themes, fonts, My Bag and more.",
    apptour_note_text: "A sticky note for the whole week. Inside, the ⚙ gear adds a 1–3 line checklist and changes its color and style.",
    apptour_peek_link: "Tasks from the AI, the calendar, goal steps and Google Calendar all show up here – plus today's calories 🔥 and your 🎯 goal of the month.",
    apptour_peek_text: "Everything for today in one place – tasks, meetings, your routine and small steps on one timeline. Tick ✓ right here.",
    apptour_date_text: "Tap it for a quick look at the monthly calendar – and add something right away.",
    apptour_date_title: "The date",
    apptour_menu_text: "Everything else waits in the menu, by topic. Here are the big ones 👇",
    apptour_welcome_text: "About five minutes: every part of the app, and then Settings. You can stop anytime and continue later.",
    apptour_welcome_title: "Hi! A tour of the whole app 👋",
