    nm_drink_added_toast: "Added ✓ {name} · {kcal} kcal",
    smart_split_study_hint: "Break a big assignment into small steps in your calendar",
    nm_drink_saved_empty_hint: "Tap ☆ to save a drink as a regular one – it will appear here and can be added with one tap.",
    nm_drink_hot_ph: "☕ Coffee / tea",
    nm_drink_milk_word: "milk",
    nm_drink_milk_ph: "🥛 Milk? How much?",
    table_select_option_delete_confirm: "This option is used in {count} rows. Delete it? Those cells will be emptied.",
    table_select_option_delete_title: "Delete option",
    faq_a_other_manual_option: "Wherever you choose from a list of options, there is also '✏️ Other' – pick it and type exactly what you need. In a table with a choice column (for example 'Relation' in a gift table), tap the cell, choose '✏️ Other', type the value (for example 'Nephew') and tap Add – it is saved as a new option of that column, so next time it is already in the list. The small × next to each option in that list deletes the option from the column. When choosing a table icon there are many icons to pick from, including colored sticky notes. It works the same way for saved-meal categories, recipe categories, recurring-expense categories (saved as a new personal category) and goal categories in My Goals.",
    faq_q_other_manual_option: "The option I need isn't in the list – what can I do?",
    select_other_missing: "Please type a value in the 'Other' field",
    select_other_placeholder: "Type here...",
    select_other_manual: "✏️ Other",
    nm_drink_est_failed: "Couldn't calculate the calories – please enter them manually",
    nm_drink_saved_toast: "Saved as a regular drink",
    nm_drink_saved_title: "My regular drinks",
    nm_drink_save_fav: "Save as a regular drink",
    nm_drink_estimating: "Calculating…",
    finance_category_new_option: "➕ New category…",
    menu_switch_to_list: "Switch to list view",
    menu_switch_to_tiles: "Switch to tiles view",
    faq_a_receipts_total: "On the Tax Invoice / Receipt screen, tap 🧮 'Total of all receipts'. Choose from which year to which year (it starts from your oldest receipt to this year), tap Calculate, and you'll see the total of both categories together – Home expenses and Business expenses – plus how many receipts there are and the total of each category separately.",
    faq_q_receipts_total: "How do I add up all my receipts for a period?",
    receipts_total_empty: "No receipts in these years.",
    receipts_total_invalid: "Please enter a valid year range",
    receipts_total_count: "{count} receipts",
    receipts_total_calc_btn: "Calculate",
    receipts_total_to_year: "To year",
    receipts_total_from_year: "From year",
    receipts_total_title: "Total of all receipts",
    receipts_total_tile: "Total of all receipts",
    faq_a_quick_note_apple: "The 🍎 next to 📝 and 🛒 in the notes window is a shortcut for quickly logging one of your saved meals to today's Daily Meal Tracker. It's on by default – if you don't need it, turn it off in Settings > Personalization & Calendar ('Show the 🍎 saved-meal shortcut in the notes window'), and turn it back on there anytime.",
    faq_q_quick_note_apple: "What is the 🍎 in the notes window, and can I hide it?",
    settings_quick_note_apple_label: "Show the 🍎 saved-meal shortcut in the notes window",
    faq_a_vision_board_today: "In My Goals, under a goal's path (in 'The plan'), tap 📅 next to a station and pick a date. You can also turn on '🔁 Every week until done' – then it comes back every week on the same day until you tick it once. The station appears on that day in My Day and in the calendar (and in Google Calendar, if it's connected), and the button shows when it's scheduled. A ✓ in either place ticks the other and moves the goal's path forward. Tap 📅 again to change the date or remove it from the calendar. Deleting a one-time task from the calendar also deletes the station from the goal; deleting one week of a weekly reminder removes only that week.",
    faq_q_vision_board_today: "How do I put a goal station in the calendar (📅)?",
    vision_milestone_already_today: "This step is already in today's tasks.",
    auth_consent_required: "To sign up, please confirm the Terms of Use and the Privacy Policy.",
