    nm_slot_drinks: "Drinks",
    faq_a_new_me_tracking: "Tap the next mission at the top of New Me and then ✓ I ate to mark the next meal as eaten – the whole menu with ✓ on every meal is in the whole day, on the side, and today's meals also appear in My Day on the home screen – a tap on one there (or the mouse over it) shows exactly what to eat, with ✓ and swap. Everything is synced with the Daily Meal Tracker: plan meals, drinks and anything you add elsewhere (for example a coffee from quick add) are counted together in New Me and in My Day – nothing you already typed is overwritten, and removing a ✓ removes only the New Me part. When all of today's meals are checked there's a small celebration. Under 'Drinks', log the day's drinks – all together up to ~150 kcal, which means about 3 drinks of up to ~50 kcal each. Just type the drink's name and the calories are filled in automatically by AI. The two coffee/tea rows also have a 'Milk? How much?' field (for example 'a little' or '50 ml'), and the calculation is updated; the number can be changed before adding and also afterwards. A drink with a name and calories is saved automatically as soon as you move on – tapping Add is optional. Tap ☆ next to a drink to save it as a regular drink – regular drinks appear as buttons at the top of the Drinks card, and one tap adds them to the day. ⭐ saves a meal as a saved meal. 'Daily table' shows what you ate with calories and protein. The small 💎 next to focus mode at the top of the home screen opens it directly. Calorie and protein values are AI estimates and may contain errors. Didn’t eat all of it? Under a checked meal, “Didn’t eat all of it?” takes off a quarter, half or three quarters of the portion – or what you write, calculated – and the day’s calories update.",
    faq_q_new_me_tracking: "How do the ✓, swaps and calories work in New Me?",
    faq_a_new_me_what: "New Me is a separate daily meal-plan program with two ready plans – 1,300 or 1,500 calories – built from 2 main meals and 2 snacks, with 3 options for each. It includes all of Premium. Price: $11.99 a month (cancel anytime) or $99.99 once for lifetime access. Open it from 💎 New Me in the menu. Before starting, there is a short questionnaire that begins with a medical disclaimer you need to accept. The program is general information only and doesn't replace a doctor or clinical dietitian.",
    faq_q_new_me_what: "What is New Me and how do I get it?",
