    food_input_placeholder: "What did you eat?", calories_input_placeholder: "Calories", protein_input_placeholder: "Protein (g)", snack_input_placeholder: "Snacks and treats...",
    nutrition_multi_food_tip: "💡 Logging a few foods in one line? Separate them with a comma or \"+\" for a more accurate calorie estimate.",
