    faq_q_daily_focus_prompt: "What's the little reminder asking what's most important for me to do today?", faq_a_daily_focus_prompt: "It's a Premium daily reminder: once a day a small \"1\" badge appears on the AI assistant icon. Tap the badge to open a bubble asking what matters most for you to do today, with 5 ready-made suggestions right there (they change daily, rotating through a whole year of different themes so they stay fresh) plus 'Other' to write your own – you can pick more than one. Tap Add, and your picks show up as small reminder tags at the top of 'My Day' (they aren't tasks to check off). If you close it with ✕ or tap outside it, the badge just fades for the rest of the day instead of disappearing. It's on by default, but you can turn it off in Settings > Personalization & Calendar. Not a day for it? Tap '🌙 Not today' – the badge disappears until tomorrow, when the question comes back as usual. One suggestion comes from your own life – the next step in your goal of the month or today's reading. Every day starts fresh.",
    food_clarify_milk_question: "Is the {ingredient} a milk-substitute mixed into the drink, or a separate solid-food serving? Please specify the amount too.",
